+    body: string,
+    replyType: 'reply' | 'replyAll' | 'forward',
+    attachments?: Attachment[]
+  ) => void;
+
+  // Modals & Overlays
+  isSettingsOpen: boolean;
+  setIsSettingsOpen: (open: boolean) => void;
