                None
              </button>
              <button
                onClick={() => handleSelectFiltered('read')}
                className="w-full text-left px-3 py-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200"
              >
                Read
