        undoAction,
        triggerUndo,
        dismissUndo,
        showToast,
        resetDemoData,

        folderCounts,
      }}
    >
      {children}
    </MailContext.Provider>
  );
};

export const useMail = () => {
  const context = useContext(MailContext);
  if (!context) {
    throw new Error('useMail must be used within a MailProvider');
  }
  return context;
};

