async function test() {
  const res = await fetch('http://127.0.0.1:9323/');
  const html = await res.text();
  console.log('Status:', res.status);
  const titleMatch = html.match(/<title>(.*?)<\/title>/);
  console.log('Title:', titleMatch ? titleMatch[1] : 'NOT FOUND');
  if (titleMatch[1] !== 'gemini-3.8-flash-high') {
    throw new Error('Title does not match gemini-3.8-flash-high');
  }

  const jsMatch = html.match(/src=\"(\/assets\/.*?\.js)\"/);
  const cssMatch = html.match(/href=\"(\/assets\/.*?\.css)\"/);

  if (jsMatch) {
    const jsRes = await fetch('http://127.0.0.1:9323' + jsMatch[1]);
    console.log('JS status:', jsRes.status, 'size:', (await jsRes.text()).length);
  }
  if (cssMatch) {
    const cssRes = await fetch('http://127.0.0.1:9323' + cssMatch[1]);
    console.log('CSS status:', cssRes.status, 'size:', (await cssRes.text()).length);
  }
  console.log('All checks passed successfully!');
}
test().catch(err => { console.error(err); process.exit(1); });
"

